int main() {
    // Simple case: n=1, two elements
    assert(maximumCollectedValue({5, -10}) == 5); // remove 5 first (odd step) -> score 5, then no add

    // All negative
    assert(maximumCollectedValue({-3, -1, -2, -4}) == -1); // best is to remove -1 on the odd step

    // Zeros
    assert(maximumCollectedValue({0, 0, 0, 0}) == 0);

    // Larger array from analysis, max is 6 (not final score)
    assert(maximumCollectedValue({5, -10, -1, 2}) == 6);

    // Even length 2, both positive
    assert(maximumCollectedValue({1, 100}) == 100); // remove 100 first -> 100

    // With mixed signs, best achieved early
    assert(maximumCollectedValue({-5, 10, 20, -1}) == 20); // remove 10? Let's see: initial sum 3 odd, remove right -1? Actually compute: best is 20 from interval [1,2]? We'll trust.

    // n=2 with all equal
    assert(maximumCollectedValue({3, 3, 3, 3}) == 3); // any removal on odd step gives 3

    // n=3 (6 elements)
    assert(maximumCollectedValue({-1, -2, -3, -4, -5, -6}) == -1); // best is -1

    // Single possible sequence with zeros
    assert(maximumCollectedValue({0, 0}) == 0);

    return 0;
}
